#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    // Initialize output bins
    bins.fill(0);

    #pragma omp parallel
    {
        // Thread-local histogram to avoid races
        std::array<size_t, 256> local{};
        local.fill(0);

        #pragma omp for
        for (std::size_t i = 0; i < image.size(); ++i) {
            const int v = image[i];
            // Assume values are in [0,255] per problem statement
            local[static_cast<unsigned>(v)]++;
        }

        // Merge local histograms into global bins safely
        #pragma omp critical
        {
            for (int k = 0; k < 256; ++k) {
                bins[static_cast<std::size_t>(k)] += local[static_cast<std::size_t>(k)];
            }
        }
    }
}
